python3 -I - <<'PY'
import json
import os
import sys

SUITES = {
    "rust": ("lint", "tests", "doc", "msrv"),
    "debian": ("debian",),
    "line-limit": (),
    "audit": (),
    "folder-limit": (),
    "python-tests": (),
    "deprecations": (),
    "sbom-and-licenses": ("supply",),
}
needs = json.loads(os.environ["NEEDS"])
problems = []

# Compared here, in code that tells `develop` from `Develop`, and not
# only in the expression that names this job.
if os.environ.get("EVENT_NAME") == "pull_request" and os.environ.get("BASE_REF") not in ("develop", "main"):
    problems.append(f"the base of this pull request is {os.environ.get('BASE_REF')!r}, not develop or main")

plan = needs.get("plan") or {}
if plan.get("result") != "success":
    problems.append(f"the plan job did not succeed (result: {plan.get('result')})")
outputs = plan.get("outputs") or {}
for dims in SUITES.values():
    for dim in dims:
        if outputs.get(dim) not in ("true", "false"):
            problems.append(f"plan output {dim!r} is neither true nor false: {outputs.get(dim)!r}")

for name in needs:
    if name != "plan" and name not in SUITES:
        problems.append(f"{name} is not in the gate table")
for name, dims in SUITES.items():
    job = needs.get(name)
    if job is None:
        problems.append(f"{name} is not among the jobs the gate waits for")
        continue
    result = job.get("result")
    if result == "success":
        continue
    if result == "skipped":
        if plan.get("result") == "success" and dims and all(outputs.get(d) == "false" for d in dims):
            continue
        problems.append(f"{name} was skipped and the plan did not say it could be")
    else:
        problems.append(f"{name} did not succeed (result: {result})")

print(f"{'suite':<20} {'plan says':<28} result")
for name, dims in SUITES.items():
    says = ",".join(f"{d}={outputs.get(d)}" for d in dims) or "always runs"
    print(f"{name:<20} {says:<28} {(needs.get(name) or {}).get('result')}")
for problem in problems:
    print(f"::error::{problem}")
if problems:
    sys.exit(1)
print("The plan succeeded and every suite passed or was skipped by the plan.")
PY
